# Code release header: applies the written labeling rule to each luminal unit and writes a rule case, a candidate label and review flags.
# Input: unit evidence and score tables of an evidence step (placeholder folder, not included), with arm values and a support vector machine class per unit.
# Output: units_rules_all_evidence_v9.csv.gz and rules.rds, plus count, cutoff and flag-rate tables.
# Counts above the SoupX ambient-RNA expectation: q < 0.05 and at least 10 UMIs. An ETS call also needs a CPM level (ERG 68, ETV1/4/5 55) and a share of at least 0.10.
# The share is the expected fraction of cells with one or more counts of the gene after thinning each cell to at most 2,000 UMIs. This depth-equalized share comes from the evidence step (not included), as share2k_<gene>.
# High tumor-like score (tl_rank_high): AMACR, PCA3 or SCHLAP1 among the unit's 1,500 highest-expressed genes (evidence step, T_rank = 1/1,500).
# Then come the nonETS tiers and the mCRPC AR and NE axes (within-mCRPC Otsu cutoffs and reference cutoffs). PAR holds most fixed cutoffs. AR_NEAR, TL_SB and TIER_ARM are set later, and the depth tests use inline values. Methods: Luminal subgroup annotation.
# AR_NEAR = 0.1: units with AR mRNA, both NEURO scores high and an AR score within 0.1 below its Otsu cutoff are AR+NE+ candidates. Without this band they would be NEPC candidates.
# Low depth means a median UMI count per cell below the G2 cutoff of the unit's chemistry (CUTS). It also means a total UMI count below the G1 cutoff, in units without ETS signal (primary) or a high AR score (mCRPC).
# G1 is PAR$G1_ETS for primary units and the refit_G1() depth for mCRPC units. refit_G1() takes the smallest tested depth at which at least 90% of thinned draws of deep AR+ mCRPC units stay AR+.
# In the run, G2 was 1,274.4 (3v2), 1,007.275 (3v3) and 3,700.15 (5p), and mCRPC G1 was 500,000 (3v2, blank) and 200,000 (3v3, 5p).
# Candidate 'normal' units were released as Benign.
# Rule layer of the luminal labeling. Rules provisional; no release label assigned.
t0 <- Sys.time(); REV <- "<PROJECT_DIR>"
.libPaths(c(file.path(REV,"redo_env_v1/Rlib_R433_overlay"),"<R_LIBRARY>",.Library))
suppressPackageStartupMessages({library(data.table);library(Matrix)}); options(width=220)
SN <- "AR"; TAG <- "all_evidence"; B <- "<work folder: this run's folder; the script writes work/rules.rds and out/tables/ under it>"; W <- file.path(B,"work"); WK <- "<input folder: holds scores.rds, the unit evidence and score tables of the evidence step>"; OUT <- file.path(B,"out/tables"); P4 <- file.path(REV,"luminal_pipeline_plan_v7"); stopifnot(unname(tools::md5sum(file.path(P4,"<input: the luminal pipeline plan file that this md5 check pins>")))=="363a8465caf86ea527a9ae187332f82f")
wr <- function(d,name,dir=OUT) { f <- file.path(dir,name); gz <- grepl("\\.gz$",name); tmp <- paste0(f,".tmp"); fwrite(d,tmp,compress=if (gz) "gzip" else "none"); system2("sync",tmp); stopifnot(file.size(tmp)>0,nrow(fread(tmp))==nrow(d)); file.rename(tmp,f) }
## ---- most fixed numbers of the rule, in one place (change one, rerun in minutes)
PAR <- list(FDR=0.05,MIN_UMI=10,LEVEL=c(ERG=68,ETV1=55,ETV4=55,ETV5=55),SHARE=0.10,G1_ETS=c(`3v2`=2e5,`3v3`=5e4,`5p`=2e5,blank=2e5) ,G1_NE=1e4,MIN_CELLS=50,L2_PCT=90,L3_FLOOR=c(CPTAC=0.005980481,TCGA=0.01661143),DN_FALSE_LOW=0.05,DN_DRAWS=50,LINEAGE_CPM=10,LINEAGE_MIN=1,S1_CPM=100,S1_LIB_FOLD=5,S1_EPI_CPM=50)
GPt <- fread(file.path(REV,"cnv_pseudobulk_pilot_v1/work/gene_positions_gtf.tsv"),header=FALSE); GP3 <- GPt$V1[match(c("AMACR","PCA3","SCHLAP1"),GPt$V2)]; SC <- readRDS(file.path(WK,"scores.rds")); U <- copy(SC$U); CUTS <- SC$CUTS; MD <- SC$MD; L3w <- SC$L3w; LG05 <- SC$LG05; EG <- c("ERG","ETV1","ETV4","ETV5"); EV <- c("ETV1","ETV4","ETV5")
g1t <- fread(file.path(P4,"tables/crpc_g1_within_cut_v4.csv")); G1AR <- g1t[share_stays_ARpos>=0.9,.(D=min(D)),by=chem_group]; G1_AR <- setNames(G1AR$D,G1AR$chem_group); print(G1_AR); G1_AR["blank"] <- max(G1_AR); G1_AR_3T <- c(`3v2`=G1_AR[["3v2"]],`3v3`=G1_AR[["3v3"]],`5p`=2e5) # 5p: 2e5, the fallback value of a depth script not included
cutv <- function(s,kind_re,l,ch=NULL) { x <- CUTS[scenario==s & grepl(kind_re,kind) & list==l]; if (is.null(ch)) x$value[1] else x$value[match(ch,x$chem)] }
tcut <- SC$Tcut; T_rank <- function(ch) { v <- tcut$T_rank[match(ch,tcut$chem3)]; v[is.na(v)] <- tcut[chem3=="pooled"]$T_rank; v }; T_log <- function(ch) { v <- tcut$T_log[match(ch,tcut$chem3)]; v[is.na(v)] <- tcut[chem3=="pooled"]$T_log; v }
## ---- same-patient pairs, from the sample metadata
pm <- MD[,.(library,study_id,patient_id,disease_state,context)]; tum <- pm[disease_state=="primary_tumor",.(tl=list(library)),by=.(study_id,patient_id)]; pairs_of <- merge(pm[disease_state %in% c("benign","BPH","normal")],tum,by=c("study_id","patient_id"),all.x=TRUE); PAIR <- setNames(pairs_of$tl,pairs_of$library); PAIR <- PAIR[!vapply(PAIR,is.null,TRUE)]; cat("non-tumor libraries with a tumor library of the same patient:",length(PAIR),"\n")
## ---- ETS rules, both readings
ets_rules <- function(d) { for (g in EG) { O <- d[[paste0("O_",g)]]; q <- d[[paste0("q_",g)]]; ro <- !is.na(q) & q<PAR$FDR & O>=PAR$MIN_UMI; set(d,NULL,paste0("ro_",g),ro); set(d,NULL,paste0("lvl_",g),ro & d[[paste0("cpm_",g)]]>=PAR$LEVEL[[g]]); set(d,NULL,paste0("shr_",g),ro & d[[paste0("share2k_",g)]]>=PAR$SHARE); set(d,NULL,paste0("e0_",g),is.na(d[[paste0("E_",g)]]) | d[[paste0("E_",g)]]==0) }
  d[,`:=`(ro_any=ro_ERG|ro_ETV1|ro_ETV4|ro_ETV5,any_e0=e0_ERG|e0_ETV1|e0_ETV4|e0_ETV5,lvl_etv=lvl_ETV1|lvl_ETV4|lvl_ETV5,shr_etv=shr_ETV1|shr_ETV4|shr_ETV5)]; d[,`:=`(lvl_any=lvl_ERG|lvl_etv,shr_any=shr_ERG|shr_etv)]; d[,`:=`(both_ERG=lvl_ERG&shr_ERG,both_etv=(lvl_ETV1&shr_ETV1)|(lvl_ETV4&shr_ETV4)|(lvl_ETV5&shr_ETV5),either_ERG=lvl_ERG|shr_ERG,either_etv=lvl_etv|shr_etv)]; d[,`:=`(both_any=both_ERG|both_etv,either_any=either_ERG|either_etv)]; d[,differ:=either_any & !both_any]; d[,share_ok:=(lvl_ERG & share2k_ERG>=PAR$SHARE)|(lvl_ETV1 & share2k_ETV1>=PAR$SHARE)|(lvl_ETV4 & share2k_ETV4>=PAR$SHARE)|(lvl_ETV5 & share2k_ETV5>=PAR$SHARE)]; d[,tl_rank_high:=tumour_like>T_rank(chem3)]; d[,tl_log_high:=tl_meanlog>T_log(chem3)]; d[,tl_either:=tl_rank_high|tl_log_high]; d[,g1_ets_low:=umi_kept<PAR$G1_ETS[chem3]]; d }
txt_g <- function(d,p) { m <- as.matrix(d[,paste0(p,EG),with=FALSE]); apply(m,1,function(r) if (any(r,na.rm=TRUE)) paste(EG[which(r)],collapse="+") else "none") }
case_primary <- function(d) { # first match. No split on read-outs or mean-log; E=0 falls through; ETV needs tumor evidence (rank-form tumor-like high, or AMACR above GSTP1; a project reading)
  v <- rep(NA_character_,nrow(d)); fl <- rep("",nrow(d)); cand <- rep("none",nrow(d)); ev <- d$tl_rank_high | (!is.na(d$amacr_minus_gstp1) & d$amacr_minus_gstp1>0)
  near <- (d$ro_ERG & d$cpm_ERG>=PAR$LEVEL[["ERG"]]/2 & d$share2k_ERG>=PAR$SHARE/2 & d$ptk %in% PT_ERG) | (d$ro_ETV1 & d$cpm_ETV1>=PAR$LEVEL[["ETV1"]]/2 & d$share2k_ETV1>=PAR$SHARE/2 & d$ptk %in% PT_ETV)
  c1 <- d$context!="primary, hormone-naive"; c2 <- !c1 & (d$g2_low | (d$g1_ets_low & !d$either_any)); c3 <- !c1 & !c2 & d$either_ERG & d$either_etv; c4 <- !c1 & !c2 & !c3 & d$both_any & (d$both_ERG | ev); c4b <- !c1 & !c2 & !c3 & d$both_any & !c4; c5 <- !c1 & !c2 & !c3 & !c4 & !c4b & d$differ; c7 <- !c1 & !c2 & !c3 & !c4 & !c4b & !c5 & near; c8 <- !c1 & !c2 & !c3 & !c4 & !c4b & !c5 & !c7 & d$tl_rank_high; c9 <- !c1 & !c2 & !c3 & !c4 & !c4b & !c5 & !c7 & !c8
  v[c1] <- "1 treated or blank"; fl[c1] <- "ets_not_called"; v[c2] <- "2 low depth"; fl[c2] <- "low_depth"; v[c3] <- "3 ERG and ETV"; fl[c3] <- "ets_mixed"; v[c4] <- "4 level and share met"; cand[c4] <- ifelse(d$both_ERG[c4],"ERG","ETV"); v[c4b] <- "4b ETV met, no tumour evidence"; fl[c4b] <- "etv_no_tumour_evidence"; v[c5] <- "5 level and share differ"; fl[c5] <- "level_share_differ"; v[c7] <- "7 near the cut in an ETS patient"; fl[c7] <- "near_cut_in_ets_patient"; v[c8] <- "8 tumour-like, no ETS"; cand[c8] <- "nonETS"; fl[c8] <- "nonets_rank_form"; v[c9] <- "9 neither"; fl[c9] <- "no_tumour_evidence"; fl[c4 & d$chem3=="5p"] <- "no_5p_control"; list(case=v,cand=cand,flag=fl) }
PT_ERG <- character(0); PT_ETV <- character(0); apply_context_first <- function(d) { d <- copy(d); d[,g2_cut:=cutv(scn_now,"^G2","median_umi",chem3)]; d[,g2_low:=!is.na(g2_cut) & median_umi<g2_cut]; ets_rules(d) }
apply_context <- function(d) { d[,g2_cut:=cutv(scn_now,"^G2","median_umi",chem3)]; d[,g2_low:=!is.na(g2_cut) & median_umi<g2_cut]; d <- ets_rules(d); d[,`:=`(candidate="none",flag="",case_v5="")]
  pr <- which(d$context %in% c("primary, hormone-naive","primary, treatment not reported","primary, treated")); if (length(pr)) { a <- case_primary(d[pr]); set(d,pr,"case_v5",a$case); set(d,pr,"candidate",a$cand); set(d,pr,"flag",a$flag) }
  ## library-level column: candidate units per library, on D4 units
  lr <- d[view=="D4" & scenario==scn_now & context=="primary, hormone-naive" & n_cells>=PAR$MIN_CELLS,.(n_c=sum(case_v5=="4 level and share met")),by=library]; d[,library_ets_units:=lr$n_c[match(library,lr$library)]]; d[is.na(library_ets_units),library_ets_units:=0L]; d[case_v5=="8 tumour-like, no ETS" & library_ets_units>0,flag:=paste(flag,"ets_unit_in_library")]
  ## benign, BPH, older: QT as proposed. Young: controls only.
  tl <- d[view=="D4" & grepl("^primary",context),.(t_erg=any(both_ERG),t_etv=any(both_etv)),by=library]; tf <- function(lib,col) vapply(lib,function(a) { z <- PAIR[[a]]; if (is.null(z)) return(FALSE); any(tl[[col]][tl$library %in% z]) },TRUE); nt <- which(d$context %in% c("benign","BPH","older donor (TS, Hirz)"))
  if (length(nt)) { x <- d[nt]; paired <- x$library %in% names(PAIR); same <- (x$both_ERG & tf(x$library,"t_erg"))|(x$both_etv & tf(x$library,"t_etv")); ben <- x$context=="benign"; cs <- fifelse(x$both_any & same & ben,"A candidate",fifelse(x$both_any,"A1 level and share, no same-patient match",fifelse(x$differ,"A2 level and share differ",fifelse(x$tl_rank_high,"B tumour-like high","C neither")))); ca <- fifelse(cs=="A candidate",fifelse(x$both_ERG,"ERG in benign sample","ETV in benign sample"),fifelse(ben,"Benign",fifelse(x$context=="BPH","BPH","normal"))); fg <- fifelse(cs=="A candidate","ets_in_benign",fifelse(cs=="A1 level and share, no same-patient match","ets_no_same_patient_match",fifelse(cs=="A2 level and share differ","level_share_differ",fifelse(cs=="B tumour-like high","tumour_like_high","")))); fg <- trimws(paste(fg,fifelse(x$g2_low,"low_depth",""),fifelse(!paired & (x$ro_any|x$either_any) & ben,"no_same_patient_tumour",""),fifelse(x$either_any & !ben,"ets_rule_in_no_tumour_context",""))); set(d,nt,"case_v5",cs); set(d,nt,"candidate",ca); set(d,nt,"flag",fg) }
  y <- which(d$context=="young donor"); if (length(y)) { set(d,y,"candidate","normal"); d[y,flag:=trimws(paste(fifelse(either_any,"ets_rule_in_control",""),"also_negative_control"))] }
  d[n_cells<PAR$MIN_CELLS & context!="mCRPC",`:=`(candidate="under 50 cells",flag=trimws(paste(flag,"under_50_cells")))]; d }
## ---- CRPC. AR axis: AR mRNA (present or absent, reference T) and AR_TCGA (target activity, within-mCRPC Otsu), read together. Cuts are project choices, unvalidated. NE arm: AR+ units by the within-mCRPC Otsu; AR- units by T, so a weak NE signal still blocks DN. Other AR lists are read-outs, never votes.
AR_G <- SC$sets$AR_TCGA; CH3 <- c("3v2","3v3","5p"); AMPC_TXT <- "AR+/NE+ candidate, unconfirmed"
## NEPC needs both NE arms at within-mCRPC Otsu; T only blocks DN. AR mRNA present with both arms: AR+/NE+ candidate if AR_TCGA is within 0.1 of the cut, else NEPC.
AR_NEAR <- 0.1; H126 <- function(arp,am,n1o,n2o,n1t,n2t,near) fifelse(arp & am & !(n1o|n2o),"AR active",fifelse(arp & am,AMPC_TXT,fifelse(arp & !am,"AR targets high, AR mRNA absent",fifelse(n1o & n2o & am & near,AMPC_TXT,fifelse(n1o & n2o,"NEPC",fifelse(am,"AR low activity, ARLPC-like",fifelse(n1o|n2o|n1t|n2t,"AR-, one NE arm","DN candidate")))))))
FLG1 <- function(p) fifelse(p==AMPC_TXT,"ar_ne_candidate_unconfirmed",fifelse(p=="AR-, one NE arm","ne_one_arm",fifelse(p=="DN candidate","dn_candidate",fifelse(p=="AR targets high, AR mRNA absent","ar_axis_discordant",fifelse(p=="low_depth","low_depth",fifelse(p=="under 50 cells","under_50_cells",""))))))
qq <- function(a,n) fifelse(is.na(a)|is.na(n),"not assessable",fifelse(a&!n,"AR",fifelse(!a&n,"NEPC",fifelse(a&n,"AR+/NE+","low/low")))); coll <- function(m) apply(m,1,function(r) paste(unique(r),collapse=" or "))
G1x <- NULL; refit_G1 <- function(d,s) { fr <- SC$SC_FR[[s]]; cu <- cutv(s,"Otsu","AR_TCGA"); pos <- d[view=="D4" & context=="mCRPC" & n_cells>=PAR$MIN_CELLS & mz_AR_TCGA>=cu & chem3 %in% c("3v2","3v3")]; Ds <- c(1e4,2e4,5e4,1e5,2e5,5e5,1e6); out <- list(); for (ch in c("3v2","3v3")) { r <- pos[chem3==ch & total_umi_use>=1e6]; if (nrow(r)<5) r <- tail(pos[chem3==ch][order(total_umi_use)],20); for (D in Ds) { set.seed(1); stay <- c(); for (u in r$unit) { tu <- r$total_umi_use[r$unit==u]; if (tu<D) next; cts <- round((2^LG05[AR_G,u]-1)*tu/1e6); for (b in 1:20) { th <- rbinom(length(cts),cts,D/tu); z <- (log2(th/D*1e6+1)-fr$mu[AR_G])/fr$sd[AR_G]; stay <- c(stay,mean(z,na.rm=TRUE)>=cu) } }; out[[length(out)+1]] <- data.table(chem_group=ch,deep_ARpos_units=nrow(r),D=D,share_stays_ARpos=round(mean(stay),3)) } }; o <- rbindlist(out); wr(o,"crpc_g1_within_cut_refit_v9.csv"); g <- o[share_stays_ARpos>=0.9,.(D=min(D)),by=chem_group]; v <- setNames(g$D,g$chem_group); cat("G1_AR refit",v,"; plan",G1_AR[c("3v2","3v3")],"\n"); c(v,`5p`=2e5,blank=max(v)) }
apply_crpc <- function(d,s,LGuse) { m <- which(d$context=="mCRPC"); d[,`:=`(crpc_axis_group="",crpc_flag="",crpc_or_form="",crpc_ar_ref="",crpc_beltran_T="",crpc_beltran_otsu="",crpc_union_otsu="",ar_cut_otsu=NA,ar_mrna_present=NA,ar_cut_ref=NA,neuro1_otsu=NA,neuro2_otsu=NA,neuro1_T=NA,neuro2_T=NA,beltran_T=NA,beltran_ar_high=NA,hallmark_ar_high=NA,labrecque_ar_high=NA,ar_lists_note="",dn_conditions="",crpc_pattern_before_depth="",pat_under_T_3v2="",pat_under_T_3v3="",pat_under_T_5p="",neuro1_pos_of_3T=NA_integer_,neuro2_pos_of_3T=NA_integer_,ar_mrna_pos_of_3T=NA_integer_)]; if (!length(m)) return(d); x <- d[m]; ct <- function(l) cutv(s,"Otsu",l); arp <- x$mz_AR_TCGA>=ct("AR_TCGA"); n1o <- x$mz_Labrecque_NEURO_I>=ct("Labrecque_NEURO_I"); n2o <- x$mz_Labrecque_NEURO_II>=ct("Labrecque_NEURO_II")
  rd <- function(k,ch) { y <- x[k]; a <- arp[k]; tt <- function(l) cutv(s,"reference T",l,ch); am <- y$ml_AR_mRNA>=tt("AR_mRNA"); n1t <- y$ml_Labrecque_NEURO_I>=tt("NEURO1"); n2t <- y$ml_Labrecque_NEURO_II>=tt("NEURO2"); n1 <- (a & n1o[k])|(!a & n1t); n2 <- (a & n2o[k])|(!a & n2t); low <- (y$median_umi<cutv(s,"^G2","median_umi",ch)) | (!a & y$total_umi_use<G1x[ch]); tnoto <- !a & n1t & n2t & !(n1o[k] & n2o[k]); p0 <- H126(a,am,n1o[k],n2o[k],n1t,n2t,abs(y$mz_AR_TCGA-ct("AR_TCGA"))<=AR_NEAR); list(tnoto=tnoto,am=am,n1t=n1t,n2t=n2t,n1=n1,n2=n2,pat0=p0,pat=fifelse(low,"low_depth",p0),or=qq(a,n1t|n2t),ref=qq(y$ml_AR_TCGA>=tt("AR20"),n1t|n2t),bel=qq(a,y$ml_NE_Beltran21>=tt("NE_Beltran21"))) }
  nag <- x$chem3=="blank"; N <- nrow(x); pat <- rep("",N); pat0 <- pat; orv <- pat; refv <- pat; belv <- pat; am <- rep(NA,N); n1t <- am; n2t <- am; arefl <- am; nbt <- am; anyne <- rep(FALSE,N); nepc_am <- anyne; tnoto_v <- anyne; p3 <- matrix("",N,3,dimnames=list(NULL,CH3)); n13 <- rep(NA_integer_,N); n23 <- n13; am3 <- n13; i <- which(!nag); if (length(i)) { r <- rd(i,x$chem3[i]); pat[i] <- r$pat; pat0[i] <- r$pat0; orv[i] <- r$or; refv[i] <- r$ref; belv[i] <- r$bel; am[i] <- r$am; n1t[i] <- r$n1t; n2t[i] <- r$n2t; anyne[i] <- r$n1|r$n2; nepc_am[i] <- r$pat0=="NEPC" & r$am; tnoto_v[i] <- r$tnoto }
  i <- which(nag); if (length(i)) { rr <- lapply(CH3,function(c3) rd(i,rep(c3,length(i)))); names(rr) <- CH3; for (c3 in CH3) p3[i,c3] <- rr[[c3]]$pat; pat[i] <- coll(p3[i,,drop=FALSE]); pat0[i] <- coll(sapply(rr,`[[`,"pat0")); orv[i] <- coll(sapply(rr,`[[`,"or")); refv[i] <- coll(sapply(rr,`[[`,"ref")); belv[i] <- coll(sapply(rr,`[[`,"bel")); n13[i] <- rowSums(sapply(rr,`[[`,"n1t")); n23[i] <- rowSums(sapply(rr,`[[`,"n2t")); am3[i] <- rowSums(sapply(rr,`[[`,"am")); nepc_am[i] <- rowSums(sapply(rr,function(q) q$pat0=="NEPC" & q$am))>0; tnoto_v[i] <- rowSums(sapply(rr,function(q) q$tnoto))>0; anyne[i] <- rowSums(sapply(rr,function(q) q$n1|q$n2))>0; am[i] <- am3[i]==3 }
